/**
 * Promo poster COMPOSER — assembles the final 1080×1350 creative with sharp:
 *
 *   Pollinations AI background (or procedural gradient fallback)
 *     + sharp hero photo (EXISTING product/model render, never regenerated)
 *     + clean offer block: ALL SAREES / ₹199 / FLAT
 *     + compact selling points + SHOP NOW pill + brand + factual footer
 *
 * HARD RULES: text is NEVER generated by the image model; the price string is
 * rendered exactly as stored in the campaign constants; the hero image is an
 * EXISTING render (Rule 6 — no regeneration).
 */
import "server-only";
import sharp from "sharp";
import {
  POSTER,
  POSTER_PALETTES,
  buildPosterGeometry,
  type PosterPalette,
  type PosterText,
} from "@/lib/marketing/promo/poster-card";
