function warmVignetteSvg(palette: PosterPalette): Buffer {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${POSTER.width}" height="${POSTER.height}">
    <defs>
      <linearGradient id="shade" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0" stop-color="#2d1009" stop-opacity="0.24"/>
        <stop offset="0.42" stop-color="#2d1009" stop-opacity="0.08"/>
        <stop offset="1" stop-color="#2d1009" stop-opacity="0.24"/>
      </linearGradient>
      <radialGradient id="glow" cx="0.72" cy="0.28" r="0.64">
        <stop offset="0" stop-color="#${palette.bgGlow}" stop-opacity="0.28"/>
        <stop offset="1" stop-color="#${palette.bgGlow}" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <rect width="${POSTER.width}" height="${POSTER.height}" fill="url(#glow)"/>
    <rect width="${POSTER.width}" height="${POSTER.height}" fill="url(#shade)"/>
  </svg>`;
  return Buffer.from(svg, "utf8");
}

async function variantBackground(variant: PosterVariant, palette: PosterPalette): Promise<Buffer> {
  const floral = `
    <g opacity="0.32" stroke="#${palette.bannerDeep}" stroke-width="2" fill="none">
      <path d="M884 98 C944 142 990 206 1006 282"/>
      <path d="M930 142 C922 104 952 84 986 92 C982 130 962 148 930 142Z" fill="#${palette.soft}" opacity="0.28"/>
      <path d="M980 238 C942 230 930 196 952 170 C988 184 1000 210 980 238Z" fill="#${palette.soft}" opacity="0.28"/>
      <path d="M92 1176 C158 1118 228 1088 304 1080"/>
      <path d="M160 1128 C122 1124 106 1094 118 1064 C154 1070 174 1092 160 1128Z" fill="#${palette.soft}" opacity="0.28"/>
    </g>`;
  const texture = `
    <g opacity="0.09">
      ${Array.from({ length: 18 }, (_, i) => {
        const y = 60 + i * 72;
        return `<path d="M0 ${y} C180 ${y + 24} 320 ${y - 28} 520 ${y + 8} S860 ${y + 46} 1080 ${y - 6}" stroke="#ffffff" stroke-width="3" fill="none"/>`;
      }).join("")}
    </g>`;
  const sideBand = `
    <path d="M876 0 C1000 178 1010 414 894 592 C776 774 790 1030 958 1350 L1080 1350 L1080 0Z" fill="#${palette.banner}" opacity="0.2"/>`;

  let defs = "";
  let body = "";
  switch (variant.bgStyle) {
    case "cream-botanical":
      defs = `
        <radialGradient id="bg" cx="0.78" cy="0.32" r="0.72">
          <stop offset="0" stop-color="#fff3dd"/>
          <stop offset="1" stop-color="#f6ead2"/>
        </radialGradient>`;
      body = `<rect width="1080" height="1350" fill="url(#bg)"/><rect x="0" y="0" width="1080" height="1350" fill="#fffaf0" opacity="0.55"/>${floral}`;
      break;
    case "dark-luxe":
      defs = `
        <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="#2d160f"/>
          <stop offset="0.55" stop-color="#5d350e"/>
          <stop offset="1" stop-color="#150b08"/>
        </linearGradient>
        <radialGradient id="lamp" cx="0.68" cy="0.34" r="0.5">
          <stop offset="0" stop-color="#d7a24c" stop-opacity="0.46"/>
          <stop offset="1" stop-color="#d7a24c" stop-opacity="0"/>
        </radialGradient>`;
      body = `<rect width="1080" height="1350" fill="url(#bg)"/><rect width="1080" height="1350" fill="url(#lamp)"/><rect x="48" y="56" width="984" height="1238" rx="0" fill="none" stroke="#d7a24c" stroke-width="3" opacity="0.28"/>`;
      break;
    case "rose-fashion":
      defs = `
        <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="#ef5d83"/>
          <stop offset="0.55" stop-color="#c2185b"/>
          <stop offset="1" stop-color="#5d0c2a"/>
        </linearGradient>`;
      body = `<rect width="1080" height="1350" fill="url(#bg)"/><circle cx="128" cy="186" r="170" fill="#ffffff" opacity="0.13"/><circle cx="952" cy="1144" r="230" fill="#ffd1e8" opacity="0.18"/>`;
      break;
    case "blue-gold":
      defs = `
        <linearGradient id="bg" x1="0" y1="0" x2="0.85" y2="1">
          <stop offset="0" stop-color="#02395d"/>
          <stop offset="0.58" stop-color="#026aa3"/>
          <stop offset="1" stop-color="#d8a42d"/>
        </linearGradient>`;
      body = `<rect width="1080" height="1350" fill="url(#bg)"/><path d="M0 1050 C220 980 382 1048 548 1000 C752 940 882 806 1080 824 L1080 1350 L0 1350Z" fill="#f9a825" opacity="0.32"/>`;
      break;
    case "sale-yellow":
      defs = `
        <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="#ffd94a"/>
          <stop offset="0.5" stop-color="#fb9f2d"/>
          <stop offset="1" stop-color="#c9301c"/>
        </linearGradient>`;
      body = `<rect width="1080" height="1350" fill="url(#bg)"/>${sideBand}<rect x="-90" y="1032" width="760" height="178" rx="0" fill="#8b0b1f" opacity="0.72" transform="rotate(-5 0 1032)"/>`;
      break;
    default:
      defs = `
        <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="#d86a34"/>
          <stop offset="0.62" stop-color="#b94a25"/>
          <stop offset="1" stop-color="#612716"/>
        </linearGradient>`;
      body = `<rect width="1080" height="1350" fill="url(#bg)"/><rect width="1080" height="1350" fill="#e98a44" opacity="0.26"/>${texture}<rect x="0" y="0" width="1080" height="1350" fill="none" stroke="#f6d6a5" stroke-width="10" opacity="0.14"/>`;
  }

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${CANVAS.width}" height="${CANVAS.height}">
    <defs>${defs}</defs>
    ${body}
  </svg>`;
  return sharp(Buffer.from(svg, "utf8")).png().toBuffer();
}

export interface ComposePosterInput {
  plan: {
    palette: string;
    sellingPoints: string[];
    backgroundPrompt: string;
    heroSide: "left" | "right";
    caption: string;
    hashtags: string[];
    engine: string;
  };
  text: PosterText;
  /** EXISTING hero image (product render / product photo) URL or path. */
  heroImageUrl: string;
  /** How many times generation was already retried (caps variation). */
  seed?: number;
  /** Force the procedural gradient even when Pollinations is configured. */
  skipComfy?: boolean;
}

export interface ComposePosterResult {
  buffer: Buffer;
  contentType: "image/jpeg";
  backgroundEngine: string;
  durationMs: number;
  seed: number;
}

/** Background: Pollinations AI when configured, deterministic gradient otherwise. */
async function buildBackground(
  plan: ComposePosterInput["plan"],
  variant: PosterVariant,
  palette: PosterPalette,
  seed: number,
  skipRemote: boolean,
): Promise<{ buffer: Buffer; engine: string; durationMs: number }> {
  if (plan.backgroundPrompt && !skipRemote) {
    const started = Date.now();
    try {
      const out = await generateImageFromText({
        prompt: `${plan.backgroundPrompt}, vibrant Indian ecommerce advertising backdrop, ${variant.bgStyle.replace("-", " ")} mood`,
        width: 1088,
        height: 1344,
        seed,
      });
      return {
        buffer: out.buffer,
        engine: `pollinations:t2i+${variant.name}`,
        durationMs: Date.now() - started,
      };
    } catch (err) {
      console.warn("[promo] Pollinations background failed, using gradient:", (err as Error).message);
    }
  }
  void plan;
  void variant;
  void palette;
  return { buffer: await variantBackground(variant, palette), engine: `local-${variant.name}`, durationMs: 0 };
}

/**
 * Compose one bright promo poster. Throws only when the hero image cannot be
 * fetched (caller falls back to the plain social card path).
 */
export async function composePoster(input: ComposePosterInput): Promise<ComposePosterResult> {
  const variant = posterVariant(input.seed ?? 0);
  const palette = POSTER_PALETTES[variant.palette ?? input.plan.palette] ?? POSTER_PALETTES.BRIGHT_POP;
  const fonts = fontsFor(variant.fontStyle);
  const geo = buildPosterGeometry(input.text);

  const bg = await buildBackground(input.plan, variant, palette, input.seed ?? 0, input.skipComfy === true);

  // HERO — existing render, kept sharp and clean. Poster text is separate.
  const { fetchImageBytes } = await import("@/lib/marketing/storage");
  const heroBytes = (await fetchImageBytes(input.heroImageUrl)).bytes;

  const hero = variant.hero;
  const heroLeft = hero.x;
  const textLeft = variant.textX;
  const heroMasked = await sharp(heroBytes)
    .resize(hero.w, hero.h, { fit: "cover", position: "attention" })
    .modulate({ brightness: 1.07, saturation: 1.22 })
    .sharpen({ sigma: 0.8, m1: 1.25, m2: 2.2 })
    .ensureAlpha()
    .composite([{ input: imageMask(hero.w, hero.h, hero.radius, variant.imageTreatment), blend: "dest-in" }])
    .png()
    .toBuffer();

  // Remote backgrounds arrive at the model's own size — normalize to the
  // canvas so no composite layer exceeds the base (sharp requirement).
  const bgBase = sharp(bg.buffer).resize(POSTER.width, POSTER.height, { fit: "cover" });

  // TEXT LAYER — sharp only, exact strings from the plan/text.
  const points = pointsSvg(input.text.sellingPoints, palette, 440, fonts, variant);
  const offer = offerBlockSvg(input.text, palette, variant.offerStyle, fonts);
  const ctaW = geo.cta.w;
  const ctaH = geo.cta.h;
  const ctaSvg = Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${ctaW}" height="${ctaH}">
       <rect x="0" y="0" width="${ctaW}" height="${ctaH}" rx="${geo.cta.radius}" fill="#${palette.cta}"/>
       <text x="${ctaW / 2}" y="${Math.round(ctaH / 2 + geo.cta.size * 0.36)}" text-anchor="middle" font-family="${fonts.display}" font-weight="900" font-size="${geo.cta.size}" letter-spacing="2" fill="#${palette.ctaText}">${esc(input.text.cta)}</text>
     </svg>`,
    "utf8",
  );
  const brandSvg = Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="620" height="150">
       <text x="0" y="76" font-family="${fonts.display}" font-weight="900" font-size="${geo.brand.size}" fill="#${palette.ink}">${esc(input.text.brand)}</text>
       <text x="4" y="114" font-family="${fonts.body}" font-weight="600" font-size="${geo.brand.taglineSize}" letter-spacing="5" fill="#${palette.soft}">${esc(input.text.tagline.toUpperCase())}</text>
     </svg>`,
    "utf8",
  );
  const footerSvg = Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="980" height="46">
       <text x="0" y="30" font-family="${fonts.body}" font-weight="600" font-size="${geo.footer.size}" fill="#${palette.soft}" opacity="0.95">${esc(input.text.handle)}   •   ${esc(input.text.productLink)}</text>
     </svg>`,
    "utf8",
  );

  const final = await sharp(await bgBase.png().toBuffer())
    .composite([
      { input: warmVignetteSvg(palette), left: 0, top: 0 },
      { input: heroMasked, left: heroLeft, top: hero.y },
      { input: offer, left: textLeft, top: variant.offerY },
      { input: await sharp(points.svg).png().toBuffer(), left: textLeft, top: variant.pointsY },
      { input: ctaSvg, left: textLeft, top: variant.ctaY },
      { input: brandSvg, left: textLeft, top: variant.brandY },
      { input: footerSvg, left: textLeft, top: variant.footerY - 30 },
    ])
    .jpeg({ quality: 96, mozjpeg: false, chromaSubsampling: "4:4:4" })
    .toBuffer();

  return {
    buffer: final,
    contentType: "image/jpeg",
    backgroundEngine: bg.engine,
    durationMs: bg.durationMs,
    seed: input.seed ?? 0,
  };
}

/** Procedural bright gradient (used when ComfyUI is off or failed). */
async function gradientFallback(plan: ComposePosterInput["plan"]): Promise<Buffer> {
  const palette = POSTER_PALETTES[plan.palette] ?? POSTER_PALETTES.BRIGHT_POP;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${POSTER.width}" height="${POSTER.height}">
    <defs>
      <linearGradient id="bg" x1="0" y1="0" x2="0.6" y2="1">
        <stop offset="0" stop-color="#${palette.bgTop}"/>
        <stop offset="1" stop-color="#${palette.bgBottom}"/>
      </linearGradient>
      <radialGradient id="glow" cx="0.78" cy="0.42" r="0.6">
        <stop offset="0" stop-color="#${palette.bgGlow}" stop-opacity="0.85"/>
        <stop offset="1" stop-color="#${palette.bgGlow}" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <rect width="${POSTER.width}" height="${POSTER.height}" fill="url(#bg)"/>
    <rect width="${POSTER.width}" height="${POSTER.height}" fill="url(#glow)"/>
  </svg>`;
  return sharp(Buffer.from(svg, "utf8")).png().toBuffer();
}
